-- V93 三年级语文上册补充题型：词语补充+选词填空 / 加点字释义 / 文言文释义
-- 共 13 题

-- q9172: node=2013 (课文4《古诗三首》填空)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2013, '语文', '三年级', '填空', 3, '{"stem": "写出下列诗句中加点字的意思。\n1. 湖光秋月两相和（和：　　）\n2. 远上寒山石径斜（斜：　　）\n3. 白云生处有人家（生：　　）\n4. 知有儿童挑促织（挑：　　）\n5. 停车坐爱枫林晚（坐：　　）\n6. 霜叶红于二月花（于：　　）", "options": null}', '1.和：和谐，协调；2.斜：倾斜，歪斜；3.生：产生，生出（指深处）；4.挑：挑动，拨动（挑促织指捉蟋蟀）；5.坐：因为；6.于：比', '古诗词字词释义。《山行》《望洞庭》《夜书所见》中常见加点字："和"取和谐之意，"坐"表原因（因为），"于"表比较（比），"挑"指拨动。', 'paper', '["加点字释义", "古诗三首", "课文4", "第四单元"]', NULL, 0, 1);

-- q9173: node=2018 (课文9《犟龟》填空)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2018, '语文', '三年级', '填空', 2, '{"stem": "先把四字词语补充完整。\n路途（　　）（　　）　　满怀（　　）（　　）　　居（　　）临（　　）\n哈哈（　　）（　　）　　日（　　）不（　　）　　（　　）（　　）糊糊", "options": null}', '路途遥远；满怀信心；居高临下；哈哈大笑；日夜不停；迷迷糊糊', '四字词语积累。根据《犟龟》课文语境补全：乌龟路途遥远仍满怀信心，居高临下眺望，日夜不停地赶路。', 'paper', '["词语积累", "四字词语", "课文9", "第三单元"]', NULL, 0, 1);

-- q9174: node=2018 (课文9《犟龟》填空)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2018, '语文', '三年级', '填空', 3, '{"stem": "选词填空。\n1. 我们站在山顶上眺望，美景尽收眼底，有一种（　　）的感觉。\n2. 他（　　）地走上演讲台，准备向全校师生分享自己的学习经验与心得。", "options": null}', '1.居高临下；2.满怀信心', '选词填空，从上面补充的四字词语中选择：站在山顶俯视是"居高临下"，自信上台是"满怀信心"。', 'paper', '["选词填空", "词语积累", "课文9", "第三单元"]', NULL, 0, 1);

-- q9175: node=2021 (课文12《在牛肚子里旅行》填空)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2021, '语文', '三年级', '填空', 2, '{"stem": "先把词语补充完整。\n七上（　　）（　　）　　争（　　）恐（　　）　　（　　）面（　　）方", "options": null}', '七上八下；争先恐后；四面八方', '词语积累。"七上八下"含反义词上/下，"四面八方"指各个方向，"争先恐后"指争着向前。', 'paper', '["词语积累", "四字词语", "课文12", "第四单元"]', NULL, 0, 1);

-- q9176: node=2021 (课文12《在牛肚子里旅行》填空)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2021, '语文', '三年级', '填空', 3, '{"stem": "选词填空（填序号）。\n一群昆虫从（　　）飞到小蜜蜂的花蜜店门口，它们（　　）地涌入店里，想要购买花蜜。\n请写出一个含有反义词的四字词语：（　　）", "options": null}', '1.四面八方；2.争先恐后；3.七上八下（含反义词"上""下"，答案不唯一，如左顾右盼、大材小用等）', '选词填空：昆虫从各个方向来用"四面八方"，争着进入用"争先恐后"。含反义词的四字词语答案不唯一。', 'paper', '["选词填空", "词语积累", "课文12", "第四单元"]', NULL, 0, 1);

-- q9177: node=2027 (课文18《美丽的小兴安岭》填空)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2027, '语文', '三年级', '填空', 2, '{"stem": "把下面词语补充完整，并选词填空。\n（　　）严（　　）实　　各种（　　）（　　）　　酸（　　）可（　　）", "options": null}', '严严实实；各种各样；酸甜可口', '词语积累。"严严实实"形容严密，"各种各样"指种类多，"酸甜可口"形容味道好。', 'paper', '["词语积累", "四字词语", "课文18", "第五单元"]', NULL, 0, 1);

-- q9178: node=2027 (课文18《美丽的小兴安岭》填空)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2027, '语文', '三年级', '填空', 3, '{"stem": "选词填空。\n1. 学校的器材室里摆满了（　　）的体育用品。\n2. 这道糖醋排骨做得（　　），让人一吃就停不下来。", "options": null}', '1.各种各样；2.酸甜可口', '选词填空：体育用品种类多用"各种各样"，糖醋排骨味道用"酸甜可口"。', 'paper', '["选词填空", "词语积累", "课文18", "第五单元"]', NULL, 0, 1);

-- q9179: node=2028 (课文19《香港，璀璨的明珠》填空)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2028, '语文', '三年级', '填空', 2, '{"stem": "把下面词语补充完整，并选词填空。\n琳琅（　　）（　　）　　当之（　　）（　　）　　（　　）（　　）多姿\n（　　）（　　）俱全　　名满（　　）（　　）　　流连（　　）（　　）", "options": null}', '琳琅满目；当之无愧；绚丽多姿；一应俱全；名满天下；流连忘返', '词语积累。"琳琅满目"形容商品多，"流连忘返"指留恋不愿离去。"（　）（　）多姿""（　）（　）俱全"两处答案参考课文语境，可能不唯一。', 'paper', '["词语积累", "四字词语", "课文19", "第五单元"]', NULL, 0, 1);

-- q9180: node=2028 (课文19《香港，璀璨的明珠》填空)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2028, '语文', '三年级', '填空', 3, '{"stem": "选词填空。\n1. 亮亮的文具盒像个\"百宝箱\"，铅笔、直尺、橡皮……各类文具（　　）。\n2. 周末，小芳和爸爸妈妈一起去游乐园，体验了各种游乐项目，开心极了，直到天黑小芳还（　　），不想离开。", "options": null}', '1.一应俱全；2.流连忘返', '选词填空：文具各类都有用"一应俱全"，天黑还不想离开用"流连忘返"。', 'paper', '["选词填空", "词语积累", "课文19", "第五单元"]', NULL, 0, 1);

-- q9181: node=2031 (课文22《读不完的大书》填空)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2031, '语文', '三年级', '填空', 2, '{"stem": "把下面词语补充完整，并选词填空。\n超（　　）脱（　　）　　秋（　　）（　　）爽　　（　　）姿（　　）态", "options": null}', '超凡脱俗；秋高气爽；千姿百态', '词语积累。"超凡脱俗"形容意境空灵，"秋高气爽"形容秋天天气，"千姿百态"形容姿态多样。', 'paper', '["词语积累", "四字词语", "课文22", "第六单元"]', NULL, 0, 1);

-- q9182: node=2031 (课文22《读不完的大书》填空)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2031, '语文', '三年级', '填空', 3, '{"stem": "选词填空。\n1. 庐山的云雾（　　），有的像飞鸟，有的像骏马。\n2. 在一个（　　）的日子里，我们一家来到黄山风景区游玩。\n3. 这幅水墨画的意境空灵悠远，尽显（　　）之美，让人观之如入仙境。", "options": null}', '1.千姿百态；2.秋高气爽；3.超凡脱俗', '选词填空：云雾形态多用"千姿百态"，秋天天气用"秋高气爽"，意境空灵用"超凡脱俗"。', 'paper', '["选词填空", "词语积累", "课文22", "第六单元"]', NULL, 0, 1);

-- q9183: node=2032 (课文23《司马光》填空)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2032, '语文', '三年级', '填空', 3, '{"stem": "先解释加点字词的意思，再解释整句话的意思。\n1. 群儿戏于庭。（戏：　　）释义：（　　）\n2. 一儿登瓮，足跌没水中。（登：　　）释义：（　　）\n3. 众皆弃去，光持石击瓮破之，水迸，儿得活。（迸：　　）释义：（　　）", "options": null}', '1.戏：嬉戏，玩耍；释义：一群小孩子在庭院里嬉戏。2.登：登上，爬上；释义：一个小孩爬上水瓮，失足跌入水中被淹没。3.迸：涌出；释义：其他小孩都（吓得）跑开了，司马光拿起石头砸破水瓮，水流出来，小孩得以活命。', '文言文词句释义。《司马光》出自《宋史》："戏"指嬉戏，"登"指爬上，"迸"指涌出。翻译时注意补全省略的主语和连贯通顺。', 'paper', '["文言文释义", "课文23", "第八单元"]', NULL, 0, 1);

-- q9184: node=2032 (课文23《司马光》填空)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2032, '语文', '三年级', '填空', 2, '{"stem": "解释下列加点字词的意思。\n庭：　　皆：　　迸：　　光：　　瓮：", "options": null}', '庭：庭院；皆：都；迸：涌出，迸发；光：指司马光；瓮：一种口小腹大的陶器', '文言文字词注释。"瓮"是口小腹大的陶器（区别于口大的"缸"），"光"在此指人名司马光。', 'paper', '["文言文字词", "课文23", "第八单元"]', NULL, 0, 1);
